"""Flask CRUD app generated by the Jinja2Compiler.
Product data and schema were extracted from the parsed Python source.
"""
from flask import Flask, render_template, request, redirect, url_for, abort

app = Flask(__name__)

# Product schema (derived from the analysed Python data): [id, name, price, in_stock, description, category]
products = [
    {"id": 1, "name": "Laptop", "price": 1200.0, "in_stock": True, "description": "Fast development laptop", "category": "Electronics"},
    {"id": 2, "name": "Headphones", "price": 250.0, "in_stock": False, "description": "Noise cancelling headphones", "category": "Audio"},
    {"id": 3, "name": "Test Product From AST", "price": 90.0, "in_stock": True, "description": "Mechanical keyboard", "category": "Accessories"},
]

def _next_id():
    return max((p["id"] for p in products), default=0) + 1

def find_product(product_id):
    return next((p for p in products if p["id"] == product_id), None)

@app.route("/")
def home():
    return redirect(url_for("list_products"))

@app.route("/products")
def list_products():
    return render_template("products.html", products=products)

@app.route("/products/<int:product_id>")
def product_details(product_id):
    product = find_product(product_id)
    if product is None:
        return render_template("not_found.html", product_id=product_id), 404
    return render_template("product_details.html", product=product)

@app.route("/products/add", methods=["GET", "POST"])
def add_product():
    errors = []
    if request.method == "POST":
        name = (request.form.get("name") or "").strip()
        price_raw = (request.form.get("price") or "").strip()
        if not name:
            errors.append("Name is required.")
        try:
            price = float(price_raw) if price_raw else 0.0
        except ValueError:
            price = 0.0
            errors.append("Price must be a number.")
        if not errors:
            products.append({
                "id": _next_id(),
                "name": name,
                "price": price,
                "in_stock": request.form.get("in_stock") == "on",
                "description": (request.form.get("description") or "").strip(),
                "category": (request.form.get("category") or "").strip(),
            })
            return redirect(url_for("list_products"))
    return render_template("add_product.html", errors=errors)

@app.route("/products/<int:product_id>/delete", methods=["POST"])
def delete_product(product_id):
    product = find_product(product_id)
    if product is not None:
        products.remove(product)
    return redirect(url_for("list_products"))

if __name__ == "__main__":
    app.run(debug=True)
